import{_ as e,H as s,f as n,i as t}from"./chunks/framework.BH2BK_3i.js";const h=JSON.parse('{"title":"43 | FeatureGates（上）：Kubernetes中的FeatureGates设计","description":"","frontmatter":{},"headers":[{"level":2,"title":"什么是 Feature Gates？","slug":"什么是-feature-gates","link":"#什么是-feature-gates","children":[]},{"level":2,"title":"如何定义一个 Feature Gates？","slug":"如何定义一个-feature-gates","link":"#如何定义一个-feature-gates","children":[]},{"level":2,"title":"Feature Gates 的生命周期","slug":"feature-gates-的生命周期","link":"#feature-gates-的生命周期","children":[]},{"level":2,"title":"在代码中使用功能门控","slug":"在代码中使用功能门控","link":"#在代码中使用功能门控","children":[{"level":3,"title":"添加新 API 字段的功能","slug":"添加新-api-字段的功能","link":"#添加新-api-字段的功能","children":[]},{"level":3,"title":"验证：无默认值的字段","slug":"验证-无默认值的字段","link":"#验证-无默认值的字段","children":[]},{"level":3,"title":"验证：有默认值的字段","slug":"验证-有默认值的字段","link":"#验证-有默认值的字段","children":[]},{"level":3,"title":"更改现有 API 字段的功能","slug":"更改现有-api-字段的功能","link":"#更改现有-api-字段的功能","children":[]},{"level":3,"title":"没有改变 API 的功能","slug":"没有改变-api-的功能","link":"#没有改变-api-的功能","children":[]}]},{"level":2,"title":"Feature Gates 的类型","slug":"feature-gates-的类型","link":"#feature-gates-的类型","children":[]},{"level":2,"title":"课程总结","slug":"课程总结","link":"#课程总结","children":[]},{"level":2,"title":"课后练习","slug":"课后练习","link":"#课后练习","children":[]}],"relativePath":"Kubernetes源码剖析与实战/43｜FeatureGates（上）：Kubernetes中的FeatureGates设计.md","filePath":"Kubernetes源码剖析与实战/43｜FeatureGates（上）：Kubernetes中的FeatureGates设计.md","lastUpdated":1795530017000}'),p={name:"Kubernetes源码剖析与实战/43｜FeatureGates（上）：Kubernetes中的FeatureGates设计.md"};function l(i,a,r,u,o,c){return s(),n("div",null,[...a[0]||(a[0]=[t(`<h1 id="_43-featuregates-上-kubernetes中的featuregates设计" tabindex="-1">43 | FeatureGates（上）：Kubernetes中的FeatureGates设计 <a class="header-anchor" href="#_43-featuregates-上-kubernetes中的featuregates设计" aria-label="Permalink to &quot;43 | FeatureGates（上）：Kubernetes中的FeatureGates设计&quot;">​</a></h1><p>你好，我是孔令飞。</p><p>在 Go 项目开发中，我们通常使用配置文件或者命令行选项来控制是否开启某个功能，这个功能可能是新加入的实验性质的功能，也可能是已经稳定的功能。总之，我们需要一种机制，来让应用进程内感知到是否开启此功能，或者此功能的配置是什么。</p><p>为此，Kubernetes 提供了一种灵活、强大的重要机制——Feature Gates（功能门控）。本节课，我就来详细介绍下 Feature Gates（简称 FG）。</p><h2 id="什么是-feature-gates" tabindex="-1">什么是 Feature Gates？ <a class="header-anchor" href="#什么是-feature-gates" aria-label="Permalink to &quot;什么是 Feature Gates？&quot;">​</a></h2><p>功能门控是 Kubernetes 中用于控制特性启用与否的一种机制。它允许开发者在集群中逐步引入新特性，便于测试和验证，同时也为用户提供了选择是否启用某些功能的灵活性。功能门控通常用于实验性特性或尚未完全稳定的功能。通过功能门控，开发者可以在不影响整个系统的情况下，逐步推出新特性。</p><p>几乎所有的软件都有漏洞，而且新软件往往比成熟的软件有更多、更严重的漏洞。FeatureGates 旨在快速停止一个新功能，并减轻漏洞带来的损害。新功能的作者和审阅者，应该花点时间思考下，Feature Gates 是否达到了这一目标。</p><p>这里需要注意，Feature Gates 并不会作为长期控制开启 / 禁用某个功能的手段。通常情况下，Feature Gates 所管控的功能在 GA 或者被弃用后，都会从 Feature Gates 中被废弃或移除。如果新功能经过验证，决定加入 Kubernetes 长期存在，那么功能的开启 / 禁用方式应该从 Feature Gates 中移除，并用其他更加适配的方式来管控，例如：配置文件、命令行选项等。</p><p>Feature Gates 中包含 2 类信息和含义：</p><ul><li><p>Feature：功能。</p></li><li><p>Gates：门控，用来控制是否开启功能。</p></li></ul><p>所以，Kubernetes 中 Feature Gate 功能其实就是用来配置某个功能是否开启的。而且这个功能，通常具有试验性质，稳定后会从 Feature Gates 中被移除，并作为稳定的功能添加到Kubernetes API 中或者主干代码中。</p><ul><li>注意：本课程从较高的维度来介绍 Feature Gates。如果你想了解更多的细节、代码片段等，请参考 api_changes.md。</li></ul><h2 id="如何定义一个-feature-gates" tabindex="-1">如何定义一个 Feature Gates？ <a class="header-anchor" href="#如何定义一个-feature-gates" aria-label="Permalink to &quot;如何定义一个 Feature Gates？&quot;">​</a></h2><p>接下来，我先来介绍下，如何定义一个功能门控。</p><p>功能门控的定义包括以下结构字段（见文件 feature_gate.go#L72）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>type FeatureSpec struct {</span></span>
<span class="line"><span>   // Default 是特性的默认启用状态。如果门控值没有明确设置，就会使用该值。</span></span>
<span class="line"><span> Default bool</span></span>
<span class="line"><span> // LockToDefault 表示特性是否锁定为默认值且不可更改。</span></span>
<span class="line"><span> LockToDefault bool</span></span>
<span class="line"><span> // PreRelease 表示特性的成熟度。可能的值有 &quot;featuregate.Alpha&quot;、&quot;featuregate.Beta&quot;、</span></span>
<span class="line"><span>   // &quot;featuregate.GA&quot; 或 &quot;featuregate.Deprecated&quot;。</span></span>
<span class="line"><span> PreRelease prerelease</span></span>
<span class="line"><span>   // Version 表示该 FeatureSpec 有效的最早版本。</span></span>
<span class="line"><span>   // 如果一个功能有多个 FeatureSpec，则使用版本号最高且小于或等于组件的有效版本的那个。</span></span>
<span class="line"><span>   Version *version.Version</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>除非某个 Feature Gate 经过 Production Readiness Review 文件的审查和批准，否则Feature Gate 预期具有以下行为：</p><ul><li><p>切换功能门控不会影响其他组件。例如：在 kube-apiserver 中禁用一个 Feature Gate，不会影响在 kubelet 或 kube-scheduler 中同一个 Feature Gate 的启用 / 禁用状态，并且组件之间不需要有关联。</p></li><li><p>切换 Feature Gate 的影响应该仅限于 Feature 的范围。启用或禁用 Feature Gate 不应影响不使用该 Feature Gate 的工作负载。</p></li><li><p>切换 Feature Gate 不应导致集群中的传播效应或级联交互。</p></li><li><p>禁用 Feature Gate 应可以防止因该特性的 Bug 造成的进一步损害。</p></li></ul><p>此外，我们还可以通过标志（见 --feature-gates）或组件配置文件（见 featureGates 配置项）启用或禁用门控，有些还可以通过环境变量启用。以及，生产环境 Kubernetes 中不支持在运行时更改 Feature Gates，通常通过重启组件来切换 Feature Gate。</p><h2 id="feature-gates-的生命周期" tabindex="-1">Feature Gates 的生命周期 <a class="header-anchor" href="#feature-gates-的生命周期" aria-label="Permalink to &quot;Feature Gates 的生命周期&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Feature Gates 中的功能一般会按顺序经历 Alpha -&gt; Beta -&gt; GA 3 个发布阶段。如果某个</span></span>
<span class="line"><span>Feature 不再被支持，可以将它们标记为 Deprecated。有些 Feature 也可能会跳过某个阶</span></span></code></pre></div><p>段，但大多数 Feature 都会经历上述 3 个阶段。</p><p>Feature 的版本在发布时，需要遵循以下规范：</p><ul><li><p>涉及 API 变更 的功能必须经过 Alpha、Beta、GA 阶段。</p></li><li><p>目标 Feature 未经过验证，或复杂性较高，或具有缺陷、风险、性能、扩展性等问题，应该经过 Alpha、Beta、GA 阶段。</p></li><li><p>目标 Feature 复杂度低且性能、扩展性影响不大，但仍然存在影响应用的风险，可能会跳过 Alpha，直接进入 Beta 阶段（前提是到达 Beta 的发布标准）。应该默认处在关闭状态，直到在生产环境中充分验证该功能。</p></li><li><p>在某些情况下，如果目标 Feature 可能导致之前正常的功能异常，需要默认关闭。</p></li><li><p>风险非常小的改动，如果想通过 Feature Gate 控制开启 / 禁用，可以选择跳过 Alpha，直接进入 Beta 阶段（前提是达到 Beta 的发布标准），并且从一开始就默认启用。</p></li><li><p>对于一些风险较高的 Bug 修复，也可以通过 Feature Gate 来控制是否开启，建议直接进入Beta 阶段，并且从一开始就默认启用。对于可能被移除的 Bug 修复，可以使用Deprecated 状态，但仍然需要确保 Bug Fix 可以被禁用。</p></li></ul><p>接下来，我们看看每个发布阶段，Feature Gate 的参数设置。</p><p>首先是 Alpha 阶段。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PreRelease 设置为featuregate.Alpha</span></span>
<span class="line"><span>Default 始终设置为 false</span></span>
<span class="line"><span>LockToDefault 设置为 false（或未指定）</span></span></code></pre></div><p>Alpha 功能默认不启用，但用户可以明确开启。</p><p>其次是 Beta 阶段。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PreRelease 设置为 featuregate.Beta</span></span>
<span class="line"><span>Default 通常设置为 true</span></span>
<span class="line"><span>LockToDefault 设置为 false（或未指定）</span></span></code></pre></div><p>Beta 功能通常默认启用（注意 beta 功能和 beta API 不同），但用户可以选择关闭该功能。</p><p>在很少的情况下，虽然 Feature Gate 是 Beta 阶段，但这个功能默认会被禁用。这告诉用户，尽管这个功能是 Beta，但该功能仍然需要一些工作，来确保该功能可以默认处在开启状态。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>例如，CSIMigration 功能门控如下所示：</span></span>
<span class="line"><span> CSIMigration:          {Default: true,  PreRelease: featuregate.Beta},</span></span>
<span class="line"><span> CSIMigrationGCE:       {Default: false, PreRelease: featuregate.Beta}, // Off b</span></span>
<span class="line"><span> CSIMigrationAWS:       {Default: false, PreRelease: featuregate.Beta}, // Off b</span></span>
<span class="line"><span> CSIMigrationAzureDisk: {Default: false, PreRelease: featuregate.Beta}, // Off b</span></span>
<span class="line"><span> CSIMigrationAzureFile: {Default: false, PreRelease: featuregate.Beta}, // Off b</span></span>
<span class="line"><span> CSIMigrationvSphere:   {Default: false, PreRelease: featuregate.Beta}, // Off b</span></span></code></pre></div><p>最后是 GA 阶段。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PreRelease 设置为 featuregate.GA</span></span>
<span class="line"><span>Default 始终设置为 true</span></span>
<span class="line"><span>LockToDefault 通常设置为 true</span></span></code></pre></div><p>GA 功能始终默认开启，并且通常不能被禁用。</p><p>在很少的情况下，一个 GA 功能可以被设置为禁用。这意味着，尽管这个功能处在 GA 状态，但用户需要时间来确保自己可以使用该功能。这给了用户一些开启的缓冲时间，但该功能最终</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>仍然会被设置为 LockToDefault=true，并像其他功能一样退役。</span></span>
<span class="line"><span>在 GA 和弃用至少 2 次发布后，Feature Gate 应该被移除。通常我们会在代码中添加 //</span></span>
<span class="line"><span>remove in 1.23 这样的注释，表示计划什么时候移除这个 Feature Gate。这样的提示可以</span></span></code></pre></div><p>使用户提前移除对功能门控的引用，否则在 Kubernetes 移除功能门控后，可能会导致程序出现异常。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>当设置为 LockToDefault=true 时，Kubernetes 还会从代码库中删除对功能门控的引用代</span></span></code></pre></div><p>码。</p><p>最后是 Deprecation。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PreRelease 设置为 featuregate.Deprecated</span></span>
<span class="line"><span>Default 设置为 false</span></span></code></pre></div><ul><li><p>你可以查看 Kubernetes 弃用政策</p></li><li><p>以获取更多详细信息</p></li></ul><p>如果 Kubernetes 用户在某个 Feature Gate 被移除时受到了影响，用户可以将该 Feature</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Gate 设置为 Default=true，然后提交 Bug。此时，Kubernetes 社区会重新考虑是否需要</span></span>
<span class="line"><span>启用该功能，并可能选择在未来 2 个版本将 Default 设置为 true，直到最终移除该</span></span></code></pre></div><p>Feature Gate。</p><p>上面介绍了 Kubernetes 添加新功能时的功能门控参数设置，但如果是功能替换，功能门控参数又该如何设置呢？</p><p>这种情况下，Kubernetes 会通过 Feature Gate 控制旧功能是否可用。在旧功能没有达到 GA</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>状态之前，Feature Gate 参数设置如下：{Default: true, PreRelease:</span></span>
<span class="line"><span>featuregate.Beta}。</span></span></code></pre></div><p>同时，Kubernetes 会将新功能以非 Feature Gate 的方式添加到 Kubernetes 代码中，供用户使用。当新的功能达到 GA 状态后，并且需要弃用旧功能时，旧功能的 Feature Gate 可以设</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>置为：{Default: false, PreRelease: featuregate.GA, LockToDefault:</span></span>
<span class="line"><span>true}。例如：LegacyNodeRoleBehavior &amp; ServiceNodeExclusion。</span></span></code></pre></div><h2 id="在代码中使用功能门控" tabindex="-1">在代码中使用功能门控 <a class="header-anchor" href="#在代码中使用功能门控" aria-label="Permalink to &quot;在代码中使用功能门控&quot;">​</a></h2><p>功能门控其实就是高级的 bool 变量，它们要么启用，要么禁用。但是，在实现功能门控的时候，有一些模式可供你遵循。</p><p>接下来，我们就看看不同功能类别下应该如何编程。我们具体讨论以下场景：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Kubernetes%E6%BA%90%E7%A0%81%E5%89%96%E6%9E%90%E4%B8%8E%E5%AE%9E%E6%88%98/images/43/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Kubernetes%E6%BA%90%E7%A0%81%E5%89%96%E6%9E%90%E4%B8%8E%E5%AE%9E%E6%88%98/images/43/1.png" alt=""></a></p><h3 id="添加新-api-字段的功能" tabindex="-1">添加新 API 字段的功能 <a class="header-anchor" href="#添加新-api-字段的功能" aria-label="Permalink to &quot;添加新 API 字段的功能&quot;">​</a></h3><p>所有新增 API 字段的功能，必须先从 Alpha 开始。这保证了功能进入 Beta 后（开始使用这些字段），可以回滚到之前的版本，而不丢失数据。用户在回滚到 Alpha 版本的时候，不保证回滚成功。</p><p>当功能门控被禁用时，系统应该表现得像这些 API 字段不存在一样。尝试使用这些 API 字段的操作，应该能够继续使用，并且新的 API 字段相关的数据需要被丢弃。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>API 注册代码（位于 pkg/registry/… 目录下），需要在 Validation 之前检查门控。如果门</span></span>
<span class="line"><span>控被禁用，并且操作时 CREATE，那么新字段必须被移除（设置为 nil）；如果门控被禁用并</span></span></code></pre></div><p>且操作时 UPDATE，那么必须检查资源对象之前的形式。只有当这个资源对象没有使用这个字段时，才可以移除新的字段。例如：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>if disabled(gate) &amp;&amp; !newFieldInUse(oldObj) {</span></span>
<span class="line"><span>   obj.NewField = nil</span></span>
<span class="line"><span>}</span></span></code></pre></div><h3 id="验证-无默认值的字段" tabindex="-1">验证：无默认值的字段 <a class="header-anchor" href="#验证-无默认值的字段" aria-label="Permalink to &quot;验证：无默认值的字段&quot;">​</a></h3><p>对于没有默认值的可选字段，API validation 时不应检查门控。相反，这种情况下的常见处理模式为：如果字段有值，则必须验证该值。这确保了在启用功能门控的条件下，对象一旦通过验证并被接受，后续的门控改变不会导致已保存对象验证失败。其实也就是说，不管该功能门控是否开启，新字段有值的时候必须检查值。</p><h3 id="验证-有默认值的字段" tabindex="-1">验证：有默认值的字段 <a class="header-anchor" href="#验证-有默认值的字段" aria-label="Permalink to &quot;验证：有默认值的字段&quot;">​</a></h3><p>对于有默认值的可选字段，这意味着新字段是必选字段，一旦 Feature Gate 功能达到 GA 阶段，并移除 Feature Gate，不应该存在这些字段没有值的情况。</p><p>这些字段的验证方法通常如下所示：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>if obj.NewField == nil {</span></span>
<span class="line"><span>   allErrs = append(allErrs, field.Required(...))</span></span>
<span class="line"><span>} else {</span></span>
<span class="line"><span>   if !newFieldValid(obj.NewField, fldPath.Child(&quot;newField&quot;)) {</span></span>
<span class="line"><span>       allErrs = append(allErrs, field.Invalid(...))</span></span>
<span class="line"><span>   }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>当功能门控处在开启状态，Validation 时必须同时考虑功能门控的开关状态、相关的 API 操作类型及资源对象之前的状态。当功能门控被禁用时，不应该校验该功能为必须项；当功能门控被开启时，应该校验该字段必须要设置值。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>API 注册代码（位于 pkg/registry/… 目录下），必须在验证之前检查门控，并传递一个标</span></span>
<span class="line"><span>志到验证逻辑中（通常作为 Option 结构中的字段）来告诉验证代码，是否需要验证新字</span></span></code></pre></div><p>段，例如：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>if enabled(gate) || newFieldInUse(oldObj) {</span></span>
<span class="line"><span>   options.EnableNewField = true</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>ValidateThisObject(obj, oldObj, options)</span></span></code></pre></div><p>然后验证代码看起来像这样：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>if opts.EnableNewField {</span></span>
<span class="line"><span>   if obj.NewField == nil {</span></span>
<span class="line"><span>       allErrs = append(allErrs, field.Required(...))</span></span>
<span class="line"><span>   } else {</span></span>
<span class="line"><span>       if !newFieldValid(obj.NewField, fldPath.Child(&quot;newField&quot;)) {</span></span>
<span class="line"><span>           allErrs = append(allErrs, field.Invalid(...))</span></span>
<span class="line"><span>       }</span></span>
<span class="line"><span>   }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>新增 API 字段时，通常需要检查功能门控。当功能门控被禁用时，系统应该表现得像新的 API字段不存在一样，API 字段虽然有值，但不会触发任何功能逻辑。这种实现可以确保：当新字段引入 Bug 需要关闭新功能时，能够消除新字段对系统的影响。</p><h3 id="更改现有-api-字段的功能" tabindex="-1">更改现有 API 字段的功能 <a class="header-anchor" href="#更改现有-api-字段的功能" aria-label="Permalink to &quot;更改现有 API 字段的功能&quot;">​</a></h3><p>对于不添加新字段，但扩展了 API 中允许的值的功能（例如，向枚举中添加值或放宽验证），功能门控必须从 alpha 开始，原因与添加新字段的功能相同。如果 Feature 不改变 API 的定义，仅仅改变了 API 的操作（如允许更新以前不可变更的字段），可以直接跳过 Alpha。</p><p>这里我们其实也能了解到，Kubernetes 对 API 定义的变更非常慎重，因为它会直接影响到外部用户是否需要改变现有的 API 接口调用，从而影响用户的体验。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>API 注册代码（位于 pkg/registry/… 目录下）必须在验证之前检查门控。与新字段的情况</span></span></code></pre></div><p>一样，此逻辑必须考虑字段的值、当前操作以及（在 UPDATE 的情况下）资源对象的先前状</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>态。类似于有默认值的新字段，它必须将一个标志传递到验证逻辑中（通常作为 Option 结</span></span></code></pre></div><p>构中的字段）来指示验证代码是否应该允许新值。验证代码实现如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>if enabled(gate) || newFieldValueInUse(oldObj) {</span></span>
<span class="line"><span>   options.AllowNewFieldValue = true</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>ValidateThisObject(obj, oldObj, options)</span></span></code></pre></div><p>这种功能的实现可能需要检查门控，也可能不需要，这取决于具体的功能。与添加新字段不同，当功能门控被禁用时，无法简单地忽略该功能的存在。功能实现必须决定在门控被禁用但功能相关的值已经被使用和存储的情况下该如何处理。</p><p>有些功能可以回退到类似的值，而有些则必须继续使用新值。重点应该放在风险控制上：如果功能存在 Bug，禁用门控应该能够停止或至少限制潜在的损害。</p><h3 id="没有改变-api-的功能" tabindex="-1">没有改变 API 的功能 <a class="header-anchor" href="#没有改变-api-的功能" aria-label="Permalink to &quot;没有改变 API 的功能&quot;">​</a></h3><p>没有改变 API 的定义，但需要修改功能实现的 Feature 可能从 alpha 开始（很少从 beta 开始）。与那些改变 API 定义的功能不同，实现逻辑是应用功能门控的唯一地方。这通常表现为</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>一个简单的 if/else 块：</span></span>
<span class="line"><span>if enabled(gate) {</span></span>
<span class="line"><span>   doNewThing()</span></span>
<span class="line"><span>} else {</span></span>
<span class="line"><span>   doOldThing()</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>与基于 API 的功能一样，系统应在功能门控被禁用时表现得像功能不存在一样。鉴于功能的多样性，“表现得像功能不存在”的确切含义必须由每个功能的实现确定。重点应放在风险缓解上：如果功能有 Bug，禁用门控应该停止或至少限制损害。</p><h2 id="feature-gates-的类型" tabindex="-1">Feature Gates 的类型 <a class="header-anchor" href="#feature-gates-的类型" aria-label="Permalink to &quot;Feature Gates 的类型&quot;">​</a></h2><p>在 Kubernetes 中，Feature Gates 分为 2 类。</p><p>首先是 FeatureGate（不可变功能门控），可以理解为只读的 Feature Gates，提供了 3 个方法，分别用来判断功能是否开启、列出所有注册的功能列表、深拷贝自身。接口定义如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// FeatureGate indicates whether a given feature is enabled or not</span></span>
<span class="line"><span>type FeatureGate interface {</span></span>
<span class="line"><span>   // Enabled returns true if the key is enabled.</span></span>
<span class="line"><span>   Enabled(key Feature) bool</span></span>
<span class="line"><span>   // KnownFeatures returns a slice of strings describing the FeatureGate&#39;s know</span></span>
<span class="line"><span>   KnownFeatures() []string</span></span>
<span class="line"><span>   // DeepCopy returns a deep copy of the FeatureGate object, such that gates ca</span></span>
<span class="line"><span>   // set on the copy without mutating the original. This is useful for validati</span></span>
<span class="line"><span>   // config against potential feature gate changes before committing those chan</span></span>
<span class="line"><span>   DeepCopy() MutableFeatureGate</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>其次是 MutableFeatureGate（可变功能门控），可以理解为可读写的 Feature Gates，除了</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>包含 FeatureGate 接口实现之外，还添加了一些写接口，用来改变 Feature Gates 内的数</span></span></code></pre></div><p>据，例如：新增功能、添加 Feature Gates 命令行 Flag。接口定义如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// MutableFeatureGate parses and stores flag gates for known features from</span></span>
<span class="line"><span>// a string like feature1=true,feature2=false,...</span></span>
<span class="line"><span>type MutableFeatureGate interface {</span></span>
<span class="line"><span>   FeatureGate</span></span>
<span class="line"><span>   // AddFlag adds a flag for setting global feature gates to the specified Flag</span></span>
<span class="line"><span>   AddFlag(fs *pflag.FlagSet)</span></span>
<span class="line"><span>   // Set parses and stores flag gates for known features</span></span>
<span class="line"><span>   // from a string like feature1=true,feature2=false,...</span></span>
<span class="line"><span>   Set(value string) error</span></span>
<span class="line"><span>   // SetFromMap stores flag gates for known features from a map[string]bool or</span></span>
<span class="line"><span>   SetFromMap(m map[string]bool) error</span></span>
<span class="line"><span>   // Add adds features to the featureGate.</span></span>
<span class="line"><span>   Add(features map[Feature]FeatureSpec) error</span></span>
<span class="line"><span>   // GetAll returns a copy of the map of known feature names to feature specs.</span></span>
<span class="line"><span>   GetAll() map[Feature]FeatureSpec</span></span>
<span class="line"><span>   // AddMetrics adds feature enablement metrics</span></span>
<span class="line"><span>   AddMetrics()</span></span>
<span class="line"><span>   // OverrideDefault sets a local override for the registered default value of</span></span>
<span class="line"><span>   // feature. If the feature has not been previously registered (e.g. by a call</span></span>
<span class="line"><span>   // locked default, or if the gate has already registered itself with a FlagSe</span></span>
<span class="line"><span>   // error is returned.</span></span>
<span class="line"><span>   //</span></span>
<span class="line"><span>   // When two or more components consume a common feature, one component can ov</span></span>
<span class="line"><span>   // default at runtime in order to adopt new defaults before or after the othe</span></span>
<span class="line"><span>   // components. For example, a new feature can be evaluated with a limited bla</span></span>
<span class="line"><span>   // overriding its default to true for a limited number of components without</span></span>
<span class="line"><span>   // changing its default for all consuming components.</span></span>
<span class="line"><span>   OverrideDefault(name Feature, override bool) error</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>在实际开发中，MutableFeatureGate 通常在应用初始化的阶段使用；FeatureGate 通</span></span></code></pre></div><p>常在应用运行阶段使用，用来判断一个功能是否开启。</p><h2 id="课程总结" tabindex="-1">课程总结 <a class="header-anchor" href="#课程总结" aria-label="Permalink to &quot;课程总结&quot;">​</a></h2><p>Kubernetes 的 Feature Gates 是控制功能启用的灵活机制，用于实验性或待稳定功能，区别于配置文件等长期管控方式。功能门控生命周期分 Alpha、Beta、GA 阶段，各阶段参数设置不同，GA 后或弃用后会被移除。本节课，我们详细介绍了 Kubernetes Feature Gates 的设计方式，并且给出了在不同场景下使用 Feature Gates 的方式。这些方式既是建议也是规范，可以让我们避免很多没必要的 Bug。</p><h2 id="课后练习" tabindex="-1">课后练习 <a class="header-anchor" href="#课后练习" aria-label="Permalink to &quot;课后练习&quot;">​</a></h2><p>请你思考下：</p><ul><li><p>在新增 API 字段时，如何验证没有默认值的新字段？</p></li><li><p>如何在代码中使用功能门控？</p></li></ul><p>欢迎你在留言区与我交流讨论，如果今天的内容让你有所收获，也欢迎转发给有需要的朋友，我们下节课再见！</p>`,104)])])}const g=e(p,[["render",l]]);export{h as __pageData,g as default};
